<?php

namespace App\Http\Requests\KnativeRegion;

use App\Models\RegionSupplyChainSetting;
use Illuminate\Foundation\Http\FormRequest;
use Illuminate\Validation\Rule;

/**
 * PUT /api/knative-regions/{knativeRegion}/supply-chain — every field optional. The signing key
 * is generated by its own endpoint and never accepted here; the admission policy is installed /
 * removed by its endpoints (admission_mode switches enforce / warn of an installed one).
 */
class UpdateRegionSupplyChainRequest extends FormRequest
{
    public function authorize(): bool
    {
        return true;
    }

    public function rules(): array
    {
        $publicKey = function (string $attribute, mixed $value, \Closure $fail) {
            if (! is_string($value) || ! str_contains($value, 'BEGIN PUBLIC KEY') || @openssl_pkey_get_public($value) === false) {
                $fail(__('supply_chain.validation.public_key'));
            }
        };

        return [
            'sbom_enabled' => 'sometimes|boolean',
            'scan_enabled' => 'sometimes|boolean',
            'scan_external_images' => 'sometimes|boolean',
            'rescan_interval_hours' => 'sometimes|integer|min:0|max:720',

            'scanner_db_mode' => ['sometimes', Rule::in(RegionSupplyChainSetting::DB_MODES)],
            'scanner_db_source' => ['sometimes', 'nullable', 'string', 'max:255', 'regex:#^[a-z0-9.-]+(:[0-9]+)?/[a-z0-9._/-]+(:[A-Za-z0-9._-]+)?$#'],

            'gate_mode' => ['sometimes', Rule::in(RegionSupplyChainSetting::GATE_MODES)],
            'gate_max_critical' => 'sometimes|nullable|integer|min:0|max:100000',
            'gate_max_high' => 'sometimes|nullable|integer|min:0|max:100000',
            'gate_only_fixable' => 'sometimes|boolean',
            'gate_require_scan' => 'sometimes|boolean',

            'signing_enabled' => 'sometimes|boolean',
            'verify_on_deploy' => 'sometimes|boolean',
            'attest_enabled' => 'sometimes|boolean',

            'admission_mode' => ['sometimes', Rule::in(RegionSupplyChainSetting::ADMISSION_MODES)],
            'admission_require_sbom' => 'sometimes|boolean',
            'admission_exempt_images' => 'sometimes|nullable|array|max:100',
            'admission_exempt_images.*' => ['string', 'max:255', 'regex:#^[A-Za-z0-9.:_/*@-]+$#'],

            'caas_policy' => ['sometimes', Rule::in(RegionSupplyChainSetting::CAAS_POLICIES)],
            'caas_allowed_registries' => 'sometimes|nullable|array|max:100',
            'caas_allowed_registries.*' => ['string', 'max:255', 'regex:#^[A-Za-z0-9.:_/*-]+$#'],
            'caas_trusted_keys' => 'sometimes|nullable|array|max:20',
            'caas_trusted_keys.*' => ['string', 'max:4096', $publicKey],

            'data_location' => ['sometimes', 'nullable', 'string', 'max:64', 'regex:/^[A-Za-z0-9][A-Za-z0-9 _.-]*$/'],
        ];
    }

    public function after(): array
    {
        return [function ($validator) {
            $policy = $this->input('caas_policy');
            $registries = $this->input('caas_allowed_registries');
            if (in_array($policy, ['allowlist', 'signed'], true) && is_array($registries) && $registries === []) {
                $validator->errors()->add('caas_allowed_registries', __('supply_chain.validation.registries_required'));
            }
            if ($policy === 'signed' && is_array($this->input('caas_trusted_keys')) && $this->input('caas_trusted_keys') === []) {
                $validator->errors()->add('caas_trusted_keys', __('supply_chain.validation.keys_required'));
            }
        }];
    }
}
